using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.Data;
using System.Text;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Forms;
using DevExpress.XtraEditors;

namespace Jamera.Items.Models
{
    public partial class Models : DevExpress.XtraEditors.XtraUserControl
    {
        public Models()
        {
            InitializeComponent();
            // This line of code is generated by Data Source Configuration Wizard
            // Fill a SqlDataSource
            sqlDataSource1.Fill();
        }

        private void gridView1_DoubleClick(object sender, EventArgs e)
        {
            if (gridView1.DataRowCount > 0)
            {
                Model model = new Model();
                model.Model_Id = Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns[0]));
                model.Model_Name = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns[1]));
                Edit_Model edit_model = new Edit_Model(model);
                edit_model.models = this;
                edit_model.Do_Refresh = true;
                edit_model.ShowDialog(this);
            }
        }
        public void Refresh_Grid_Data()
        {
            search_inp.Text = null;
            this.Enabled = false;
            sqlDataSource1.RebuildResultSchema();
            sqlDataSource1.Fill();
            list.Update();
            this.Enabled = true;
        }
        private void refresh_btn_Click(object sender, EventArgs e)
        {
            Refresh_Grid_Data();
            search_inp.Focus();
        }

        private void create_new_btn_Click(object sender, EventArgs e)
        {
            search_inp.Focus();
            New_Model new_model = new New_Model();
            new_model.models = this;
            new_model.Do_Refresh = true;
            new_model.ShowDialog(this);
        }

        private void search_inp_EditValueChanged(object sender, EventArgs e)
        {
            gridView1.ApplyFindFilter(search_inp.Text);
        }
    }
}
